 {
  private static readonly Dictionary<string,WaveformPeaks> Cache=new Dictionary<string,WaveformPeaks>(StringComparer.OrdinalIgnoreCase);private static readonly HashSet<string> Loading=new HashSet<string>(StringComparer.OrdinalIgnoreCase);private static readonly object Sync=new object();
  public static WaveformPeaks Get(string path,Control owner){if(String.IsNullOrEmpty(path))return null;lock(Sync){WaveformPeaks p;if(Cache.TryGetValue(path,out p))return p;if(Loading.Contains(path))return null;Loading.Add(path);}Task.Factory.StartNew(delegate{WaveformPeaks result=new WaveformPeaks{Peaks=new float[0]};try{CachedAudio data=CachedAudio.Load(path);int count=(int)Math.Min(8192,data.Frames);float[] peaks=new float[count];for(int i=0;i<count;i++){long a=i*data.Frames/count,b=Math.Max(a+1,(i+1)*data.Frames/count);float max=0;for(long frame=a;frame<b;frame++)for(int c=0;c<data.Channels;c++)max=Math.Max(max,Math.Abs(data.Samples[frame*data.Channels+c]));peaks[i]=max;}result.Peaks=peaks;result.Duration=data.Frames/(double)data.Rate;}catch{}lock(Sync){Cache[path]=result;Loading.Remove(path);}try{if(owner.IsHandleCreated&&!owner.IsDisposed)owner.BeginInvoke((Action)delegate{owner.Invalidate();});}catch{}});return null;}
  public static void Draw(Graphics g,Rectangle rect,string path,double offset,double seconds,Control owner,Color color){WaveformPeaks p=Get(path,owner);if(p==null||p.Peaks.Length==0||p.Duration<=0||rect.Width<=0)return;using(Pen pen=new Pen(color,1)){for(int x=0;x<rect.Width;x++){double time=offset+x/(double)rect.Width*seconds;int i=(int)(time/p.Duration*p.Peaks.Length);if(i<0||i>=p.Peaks.Length)continue;float h=Math.Max(0.5f,p.Peaks[i]*rect.Height*.48f);g.DrawLine(pen,rect.X+x,rect.Y+rect.Height/2-h,rect.X+x,rect.Y+rect.Height/2+h);}}}
 }
